#!/usr/bin/env python3
"""Random valid request generator for differential testing."""
import json, random, string

NUM = ('TIME','SIZE','COUNT')

def gen_field(rng, idx):
    ty = rng.choice(['TIME','SIZE','COUNT','ID','FLAG','FLAG','ID'])
    name = 'f%d' % idx
    if ty in NUM:
        lo = rng.randint(-5, 20); hi = rng.randint(lo, lo+30)
        return {'name':name,'type':ty,'min':lo,'max':hi}
    if ty == 'ID':
        pool = ['a','b','c','d:e','f.g','h-i','j_k','l.m','n:o','p.q']
        rng.shuffle(pool)
        k = rng.randint(1, min(5, len(pool)))
        return {'name':name,'type':'ID','values':pool[:k]}
    return {'name':name,'type':'FLAG'}

def gen_term(rng, ftypes, ty, depth, inq, K, allow_dollar=True):
    """Return a term AST of type ty with depth <= depth."""
    opts = []
    # field
    cands = [i for i,t in enumerate(ftypes) if t == ty]
    if cands:
        opts.append('field')
    opts.append('const')
    if ty in NUM:
        opts.append('aggregate')
        if depth >= 2:
            opts.append('scale')
            opts.append('add')
    kind = rng.choice(opts)
    if kind == 'field':
        i = rng.choice(cands)
        if inq and allow_dollar and rng.random() < 0.5:
            at = '$'
        else:
            at = rng.randrange(K)
        return {'field':'f%d'%i,'at':at}
    if kind == 'const':
        if ty in NUM:
            return {'const':rng.randint(-10,30),'type':ty}
        if ty == 'ID':
            pool=['a','b','zz','q.r','s:t']
            return {'const':rng.choice(pool),'type':'ID'}
        return {'const':rng.choice([True,False]),'type':'FLAG'}
    if kind == 'aggregate':
        i = rng.choice(cands)
        a = rng.randrange(K); b = rng.randrange(a, K)
        return {'aggregate':rng.choice(['sum','mean','min','max']),
                'field':'f%d'%i,'from':a,'to':b}
    if kind == 'scale':
        return {'scale':rng.randint(-3,5),
                'term':gen_term(rng,ftypes,ty,depth-1,inq,K,allow_dollar)}
    # add
    return {'add':[gen_term(rng,ftypes,ty,depth-1,inq,K,allow_dollar),
                   gen_term(rng,ftypes,ty,depth-1,inq,K,allow_dollar)]}

def gen_cmp(rng, ftypes, inq, K):
    tys = list(ftypes) + ['TIME','SIZE','COUNT','ID','FLAG']
    ty = rng.choice(tys)
    if ty in NUM:
        op = rng.choice(['eq','ne','lt','le','gt','ge'])
    else:
        op = rng.choice(['eq','ne'])
    d = rng.choice([1,1,2,2,3,4])
    return {'cmp':op,
            'left':gen_term(rng,ftypes,ty,d,inq,K),
            'right':gen_term(rng,ftypes,ty,d,inq,K)}

def gen_atom(rng, ftypes, K):
    if rng.random() < 0.3:
        a = rng.randrange(K); b = rng.randrange(a, K)
        return {'quantifier':rng.choice(['any','all']),'from':a,'to':b,
                'predicate':gen_cmp(rng,ftypes,True,K)}
    return gen_cmp(rng,ftypes,False,K)

def gen_request(rng):
    K = rng.randint(1,4)
    nf = rng.randint(1,5)
    schema = [gen_field(rng,i) for i in range(nf)]
    ftypes = [f['type'] for f in schema]
    atoms = [gen_atom(rng,ftypes,K) for _ in range(rng.randint(0,4))]
    pol = {'max_width':rng.randint(1,3),
           'min_support':rng.randint(1,3),
           'min_witness':rng.randint(1,3)}
    srcs = ['lab','prod','test'][:rng.randint(1,3)]
    parts = {}
    tid = 0
    for key in ('train','probes','queries'):
        traces = []
        for _ in range(rng.randint(0,3)):
            n = rng.randint(0, K+3)
            ts = rng.sample(range(0, 40), n)
            rows = []
            for t in ts:
                vals = []
                for f in schema:
                    ty = f['type']
                    if ty == 'FLAG': vals.append(rng.random() < 0.5)
                    elif ty == 'ID': vals.append(rng.choice(f['values']))
                    else: vals.append(rng.randint(f['min'], f['max']))
                rows.append({'t':t,'values':vals})
            rng.shuffle(rows)
            traces.append({'id':'t%d'%tid,'source':rng.choice(srcs),'rows':rows})
            tid += 1
        parts[key] = traces
    return {'version':1,'schema':schema,'window':K,'atoms':atoms,'policy':pol,
            'train':parts['train'],'probes':parts['probes'],'queries':parts['queries']}

if __name__ == '__main__':
    import sys
    seed = int(sys.argv[1])
    rng = random.Random(seed)
    json.dump(gen_request(rng), sys.stdout)
